import sys
from collections import defaultdict, deque

def find_shortest_cycle(n, file_names, adj_list):
    def bfs(start):
        visited = {start: 0}
        queue = deque([start])
        parent = {start: None}
        while queue:
            node = queue.popleft()
            for neighbor in adj_list[node]:
                if neighbor not in visited:
                    visited[neighbor] = visited[node] + 1
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif parent[node] != neighbor:
                    cycle = []
                    x = node
                    while x != neighbor:
                        cycle.append(x)
                        x = parent[x]
                    cycle.append(neighbor)
                    cycle.append(node)
                    return cycle[::-1]
        return None

    for file in file_names:
        cycle = bfs(file)
        if cycle:
            return cycle
    return None

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    file_names = input[1].split()
    adj_list = defaultdict(list)
    index = 2
    for _ in range(n):
        file, k = input[index].split()
        k = int(k)
        if k > 0:
            adj_list[file] = input[index + 1].split(', ')[1:]
        index += k + 1

    cycle = find_shortest_cycle(n, file_names, adj_list)
    if cycle:
        print(' '.join(cycle))
    else:
        print('SHIP IT')

main()
